L["0 hides it (the default): it shows only while the buff is missing."] = "0 表示隐藏（默认）：仅在增益缺失时显示。"
L["0 hides it while the hand has no weapon to enchant."] = "设为0时，若该手没有可附魔的武器则隐藏。"
