L["0 is normal. A higher priority wins the screen spot and is the last out of a full queue. Ties follow Overlap Behavior."] = "0为正常。优先级更高者占据屏幕位置，并在队列已满时最后被移除。优先级相同时按“重叠行为”处理。"
