L["A blank layout. Add your own groups, icons and bars."] = "空白布局。自行添加组、图标和状态条。"
L["A buff or debuff as an icon; several IDs can light one icon."] = "以图标显示的增益或减益效果；多个 ID 可以点亮同一个图标。"
L["A cast that finishes, one that is interrupted, then a channel."] = "一次完成的施法，一次被打断的施法，然后是一次引导。"
L["A cast while it runs: start it over, add the seconds to what is left, leave it running, or end it."] = "计时器运行期间再次施放：重新开始、把秒数加到剩余时间上、保持运行，或将其结束。"
L["A charge left and another coming back, over and over: the Recharging look, with its opacity, grey out, tint and glow."] = "剩余一次充能，另一次正在恢复，如此循环：显示“充能中”样式，含其不透明度、去色、着色和发光。"
L["A condition holds"] = "某个条件成立"
