L["A condition turns on"] = "某个条件变为开启"
L["A cooldown ID names a Cooldown Manager icon, so it stays at its own spot."] = "冷却ID指向冷却管理器图标，所以保持在自己的位置。"
L["A cooldown ID names a Cooldown Manager icon."] = "冷却ID指向冷却管理器图标。"
L["A deck bar fills as the deck is drawn, with a mark for each proc."] = "牌组条随牌组被抽取而填充，每次触发都有一个标记。"
L["A deck of 100 stacks holding 2 Tempest procs."] = "一副 100 层的牌组，含 2 次狂风怒号触发。"
L["A deck of 250 stacks holding 5 Storm Unleashed procs."] = "一副 250 层的牌组，含 5 次风暴释放触发。"
L["A deck of 333 Maelstrom holding 2 Tempest procs."] = "一副 333 点漩涡值的牌组，含 2 次狂风怒号触发。"
L["A deck of 333 stacks holding 2 Ascendance procs."] = "一副 333 层的牌组，含 2 次升腾触发。"
L["A deck of 600 Maelstrom Weapon stacks holding 3 Doom Winds procs."] = "一副 600 层漩涡武器的牌组，含 3 次毁灭之风触发。"
L["A dim dark line along the edge, under the moving lines."] = "沿边缘的一条暗淡的深色线，位于移动的线条下方。"
L["A divider where each stage of an empowered cast begins, in the tick look. Shows with tick marks off too."] = "在蓄力法术每个阶段开始处显示分隔线，使用刻度样式。关闭刻度标记时也会显示。"
L["A female voice"] = "女声"
L["A fill, like a bar"] = "像状态条一样的填充"
L["A glow around the bar, with a trigger of its own. Works in combat."] = "状态条周围的发光，有自己的触发器。战斗中也有效。"
L["A grid of small tiles showing the art and the name. Click a tile to edit it. Hover it for its details, Edit and Delete."] = "由小图块组成的网格，显示图像和名称。点击图块可编辑。鼠标悬停可查看详情、编辑和删除。"
L["A group needs at least one column."] = "组至少需要一列。"
