L["A layout for 1 class"] = "适用于1个职业的布局"
L["A layout pack you use has a newer version."] = "你使用的某个布局包有了新版本。"
L["A look of its own under a time left"] = "剩余时间低于某值时使用独立的样式"
L["A look under a time left"] = "剩余时间低于某值时的样式"
L["A male voice"] = "男声"
L["A mark where each spell's cost is met. It shows with Tick marks on (Appearance > Ticks)."] = "在每个法术的消耗被满足的位置显示一个标记。开启“刻度标记”（外观 > 刻度）后显示。"
L["A mark where your next spell can be queued: press it past the mark and it goes off as soon as this cast ends."] = "标出下一个法术可以排队的位置：在标记之后按下，它会在本次施法结束时立即施放。"
L["A missing aura"] = "缺失的光环"
L["A name, version, link and notes for your pack. Whoever imports the string sees them first."] = "你的包的名称、版本、链接和说明。导入字符串的人会先看到这些。"
L["A named frame"] = "一个已命名的框架"
L["A nameplate: not offered"] = "姓名板：不提供"
L["A newer version is out: click to update your copy"] = "有新版本：点击更新你的副本"
L["A newer version of this layout is out. Updates the layout you made from it; your own sizes and positions stay."] = "这个布局有了新版本。会更新你由它创建的布局；你自己的尺寸和位置会保留。"
L["A percent of the bar, or power with In power units on."] = "状态条的百分比；开启“以资源值为单位”后则为资源值。"
L["A picture of your own: its FileDataID, or its path such as Interface/AddOns/MyMedia/glow. Enter applies it; empty = pick one above."] = "你自己的图片：其 FileDataID，或路径，如 Interface/AddOns/MyMedia/glow。按 Enter 应用；留空 = 从上方选择。"
L["A picture that follows an aura, a cooldown, your power, health or triggers."] = "跟随光环、冷却、你的资源、生命值或触发器变化的图片。"
L["A power bar; Automatic follows the power you are using."] = "一个资源条；“自动”会跟随你正在使用的资源。"
L["A proc glow ended"] = "触发发光已结束"
L["A proc glow started"] = "触发发光已开始"
L["A proc shows it at full opacity"] = "触发时以完全不透明显示"
L["A quarter turn: the bar becomes tall and thin, and its icon, texture and gradient turn with it."] = "旋转90度：状态条变得又高又窄，其图标、材质和渐变也随之旋转。"
L["A reactive ability lit up"] = "一个反应技能亮起"
L["A reminder exported on its own joins this group. A group keeps one reminder per spell, item or weapon hand, so duplicates stay out."] = "单独导出的提醒会加入此组。每个法术、物品或主副手武器只保留一个提醒，因此重复项不会加入。"
L["A returning icon"] = "重新出现的图标"
L["A ring of your spells and items: hold its key, point at one and let go to cast it."] = "由你的法术和物品组成的圆环：按住它的快捷键，指向其中一个并松开即可施放。"
L["A ring, like a cooldown"] = "像冷却一样的圆环"
L["A set duration"] = "固定的持续时间"
L["A share of the time"] = "时间的一定比例"
L["A short flash"] = "短暂的闪烁"
