L["A skin made from the default look. A bar's Skin dropdown makes one from that bar's look."] = "由默认样式制作的皮肤。状态条的“皮肤”下拉菜单会用该状态条的样式制作一个。"
L["A soft glow around the icon in this type's color. Glow size is under All."] = "图标周围以此类型的颜色显示柔和的发光。发光大小在“全部”下设置。"
L["A spare profile in Arc UI: its groups and icons come in switched off; turn them on in their Load tab."] = "Arc UI 中的备用配置：其组和图标导入时为关闭状态；请在它们的“载入”标签页中开启。"
L["A spark crosses the bar every 2 seconds and lands on each mana tick."] = "火花每2秒掠过状态条一次，并落在每次法力回复跳上。"
