L["A spell ID, a link, or the name of a spell you know. Any rank of it counts unless Only this rank is on."] = "法术 ID、链接，或你已学会的法术名称。只要未开启“仅此等级”，它的任何等级都算。"
L["A spell ID, a link, or the name of a spell you know. Enter applies it."] = "法术 ID、链接，或你已学会的法术名称。按 Enter 应用。"
L["A spell ID, a spell link, or the name of a spell in your spellbook: for spells the catalog does not list."] = "法术 ID、法术链接，或你法术书中的法术名称：用于目录中没有列出的法术。"
L["A spell ID, or the name of a spell you know. Any rank works: the bar follows the rank you know."] = "法术 ID，或你已学会的法术名称。任何等级都可以：状态条会跟随你已学会的等级。"
L["A spell ID, or the name of a spell you know. It goes on the first empty spot; one you have not learned yet shows grey until you do."] = "法术 ID，或你已学会的法术名称。它会放到第一个空位；尚未学会的法术会显示为灰色，直到你学会为止。"
