L["Emity's latest version: Dark Inspiration, anchors for more player frames, and stack counts from 1."] = "Emity 的最新版本：Dark Inspiration、适配更多玩家框体的锚点，以及从 1 层起显示层数。"
L["Emity's latest version: Incinerate, Conflagrate and Soul Fire, Demon Skin in Missing Buffs, anchors for more player frames, and stack counts from 1."] = "Emity 的最新版本：烧尽、燃烧和灵魂之火、缺失增益中的恶魔皮肤、适配更多玩家框体的锚点，以及从 1 层起显示层数。"
L["Emity's latest version: Maelstrom Weapon and mana bars for Enhancement, Elemental Mastery, anchors for more player frames, and stack counts from 1."] = "Emity 的最新版本：增强专精的漩涡武器和法力条、元素掌握、适配更多玩家框体的锚点，以及从 1 层起显示层数。"
L["Emity's latest version: Reckoning, the new Vindication, Blessing of Freedom, anchors for more player frames, and stack counts from 1."] = "Emity 的最新版本：清算、新的辩护、自由祝福、适配更多玩家框体的锚点，以及从 1 层起显示层数。"
L["Emity's latest version: Revenge and Overpower icons that light up when you can use them."] = "Emity 的最新版本：复仇和压制可用时会亮起的图标。"
L["Emity's latest version: Scorpid Sting, Scatter Shot and Expose Prey on your target, both hawks, your off-hand enchant, anchors for more player frames, and stack counts from 1."] = "Emity 的最新版本：目标身上的蝎毒钉刺、驱散射击和 Expose Prey、两只鹰、你的副手附魔、适配更多玩家框体的锚点，以及从 1 层起显示层数。"
L["Emity's latest version: a Thousand Cuts bar for Subtlety, anchors for more player frames, and stack counts from 1."] = "Emity 的最新版本：敏锐专精的 Thousand Cuts 状态条、适配更多玩家框体的锚点，以及从 1 层起显示层数。"
L["Emity's latest version: bars for Arcane Blast, Heating Up and Fingers of Frost, Arcane Wrath, anchors for more player frames, and stack counts from 1."] = "Emity 的最新版本：奥术冲击、热力迸发和寒冰指状态条、Arcane Wrath、适配更多玩家框体的锚点，以及从 1 层起显示层数。"
L["Emity's latest version: missing buff reminders show only for spells you know."] = "Emity 的最新版本：缺失增益提醒只针对你已学会的法术显示。"
