L["Hides between casts; shows a sample cast while this window is open."] = "两次施法之间隐藏；此窗口打开期间会显示一次示例施法。"
L["Hides casts you cannot interrupt. In combat the game hides that from addons, so it cannot drive sounds or alerts."] = "隐藏无法打断的施法。战斗中游戏会对插件隐藏这一信息，因此无法用于触发声音或警报。"
L["Hides it on screen while this window is open, so you can get at what sits under it. Closing the window shows it again."] = "此窗口打开期间在屏幕上隐藏它，方便你操作它下方的内容。关闭窗口后会再次显示。"
L["Hides the game's castbar under your character while this castbar is loaded. Turn off to bring it back on your next cast."] = "此施法条载入期间，隐藏角色下方的游戏施法条。关闭后，下次施法时恢复显示。"
L["Hides the minimap button. %s always opens this window. Drag the button along the rim to move it, right-click for move mode."] = "隐藏小地图按钮。%s 始终可以打开此窗口。沿边缘拖动按钮可移动它，右键点击可切换移动模式。"
L["Hides this update here until the next version. The tag on the layout in the sidebar stays."] = "在下个版本之前隐藏此处的这个更新。侧边栏中布局上的标签仍会保留。"
L["Hides while the unit is not there; always shows while this window is open."] = "单位不存在时隐藏；此窗口打开期间始终显示。"
