L["Holds while the aura is up at this many stacks. Its effects apply only then."] = "光环存在且层数为此数量期间成立。其效果仅在此时生效。"
L["Holds while the spell has this many charges. Its effects apply only then; in a Dynamic group it keeps its place."] = "法术的充能次数为此数量期间成立。其效果仅在此时生效；在动态组中图标保持原位。"
