L["Horizontal packs each row sideways; Vertical packs each column up or down."] = "水平会把每一行横向排列；垂直会把每一列向上或向下排列。"
L["Hot chance color"] = "高概率颜色"
L["Hot from (%)"] = "高概率起始值（%）"
L["Hover a game frame on screen and click it. Right-click or Esc cancels."] = "将鼠标移到屏幕上的某个游戏框架上并点击。右键点击或按 Esc 取消。"
L["Hover a game frame or one of your Arc Auras items and click it. On an icon in a group, Shift-click takes the icon."] = "将鼠标悬停在游戏框架或你的 Arc Auras 元素上并点击。在组内的图标上，Shift+点击会选取该图标。"
L["Hover a game frame, an action button, a Cooldown Manager icon or an Arc Auras icon and left-click it. Right-click or Esc cancels."] = "将鼠标移到某个游戏框架、动作按钮、冷却管理器图标或 Arc Auras 图标上并左键点击。右键点击或按 Esc 取消。"
L["Hovering an icon shows its spell, item or totem tooltip."] = "鼠标悬停在图标上时，会显示其法术、物品或图腾的鼠标提示。"
L["How big the preview is against the bar's real size. Click to fit the whole bar in view again."] = "预览相对于状态条实际大小的比例。点击可让整条状态条重新适应视野。"
L["How countdown numbers round. Up: 13.2 reads 14, like action bar cooldowns. Down: 13.2 reads 13, like buff timers and nameplates."] = "倒计时数字的取整方式。向上：13.2 显示为 14，与动作条冷却相同。向下：13.2 显示为 13，与增益计时器和姓名板相同。"
L["How far the glow reaches past the icon: 1 sits on its edge."] = "发光向图标外延伸的距离：1 表示紧贴图标边缘。"
L["How far your target is, in colored range bands you can edit."] = "你的目标有多远，以可编辑的彩色距离区间显示。"
L["How fast a line is spoken. 0 follows WoW's own speech rate."] = "一句话的语速。0 表示跟随 WoW 自己的语速。"
L["How it looks in each state"] = "各状态下的样式"
L["How it shows"] = "显示方式"
L["How long a flash shows. A held button keeps the highlight at least this long, so clicks that cast on release still show."] = "闪烁显示的时长。按住按钮时，高亮至少会保持这么久，因此松开时才施放的点击也能显示。"
L["How long after that rule last fired this one may fire (Not after: may not fire). Enter applies it."] = "在那条规则上次触发后多久，这一条才可以触发（“不在其后”：则不可触发）。按 Enter 应用。"
L["How long after your cast it may land and still light this in combat. One that flies in first needs longer (Summon Hawk: 1.5 s)."] = "施法后多久内出现仍会在战斗中点亮此项。先飞过去的需要更久（Summon Hawk：1.5 秒）。"
L["How long it shows after each cast."] = "每次施法后显示多久。"
L["How long the bar takes to fade away when a cast ends (after the hold, when that is on). 0 = it goes at once."] = "施法结束后，条淡出消失所需的时间（若开启了保持，则在保持结束后）。0 = 立即消失。"
L["How long the button glow takes to fade when it stops. 0: it goes at once."] = "按钮发光停止时淡出所需的时间。0：立即消失。"
L["How long the timer runs when a rule starts it with no seconds of its own. Enter applies it."] = "规则启动计时器却未给出秒数时，计时器运行多久。按 Enter 应用。"
L["How long the timer runs, and each stack when stacks run out on their own, when a rule gives no seconds. Enter applies it."] = "规则未给出秒数时，计时器的运行时间；层数各自到期时，则为每一层的时间。按 Enter 应用。"
L["How long the timer runs, or an added stack lasts; 0 takes the item's Default seconds. Decimals work (1.5). Enter applies it."] = "计时器运行多久，或新增的层持续多久；0 表示采用该项目的默认秒数。可以用小数（1.5）。按 Enter 应用。"
L["How long, in seconds; decimals work (1.5). Enter applies it."] = "时长，单位为秒；可以用小数（1.5）。按 Enter 应用。"
L["How many"] = "数量"
L["How many charges are up; Blank at zero below hides the 0."] = "有多少次充能可用；下方的“为0时留空”会隐藏 0。"
L["How many in your party or raid have a buff."] = "你的小队或团队中有多少人拥有某个增益。"
L["How many nameplates get a row, in the order the game numbers them. Each one keeps a set of frames ready."] = "有多少个姓名板获得一行，按游戏编号的顺序。每个姓名板都会预先备好一组框架。"
L["How many rows of auras show, each Columns wide; up to 40 auras. The rest show as others end."] = "显示多少行光环，每行宽度为“列数”；最多 40 个光环。其余的会在其他光环结束后显示。"
L["How many stacks the next spender eats; the chance is for that many draws."] = "下一个消耗技能会消耗多少层；概率按这么多次抽取计算。"
L["How many stage colors to list and show while editing; set it to your spell's stages."] = "列表中及编辑时显示的阶段颜色数量；设为你法术的阶段数。"
L["How many you carry, on items that stack, such as potions."] = "可堆叠物品（如药水）的携带数量。"
L["How the bar looks in each state"] = "各状态下条的样式"
