L["Off: a Nature wolf's arrival counts as the proc. On: the Cooldown Manager's Doom Winds icon does, so keep it shown there."] = "关闭：自然狼的出现算作触发。开启：改为冷却管理器中的毁灭之风图标算作触发，因此请保持它在那里显示。"
