L["Off: every %s loads them, each by its own specs and talents. Cast bars always stay on %s."] = "关闭：每个%s都会载入它们，各自按自己的专精和天赋。施法条始终只留在%s上。"
L["Off: silent while you are in a party."] = "关闭：你在小队中时保持静默。"
