L["On ranked realms, track whichever rank of this spell you currently know. Re-resolves on spell changes."] = "在有法术等级的服务器上，追踪你当前已学会的此法术的任一等级。法术变化时会重新解析。"
L["On screen"] = "在屏幕上"
L["On the Cooldown Manager icon for %s."] = "在 %s 的冷却管理器图标上。"
