L["On the action button with %s."] = "在带有 %s 的动作按钮上。"
L["On the bar"] = "在条上"
L["On the group"] = "在组上"
L["On the icon with cooldown ID %s."] = "在冷却 ID 为 %s 的图标上。"
L["On this icon"] = "在此图标上"
L["On top"] = "叠于其上"
L["On unit"] = "在单位上"
L["On use (when cast)"] = "使用时（施放时）"
L["On your screen"] = "在你的屏幕上"
L["On: adding stacks also starts the timer over, with the seconds below."] = "开启：添加层数时也会让计时器重新开始，使用下方的秒数。"
L["On: every Arc Proc resets the moment a key starts, so a reset is never missed. Off: on the gate drop, which keeps the skip working."] = "开启：每个 Arc 触发在钥石开始的瞬间重置，因此不会漏掉重置。关闭：在大门落下时重置，这样跳过功能仍可正常使用。"
L["On: icons pack (Show while missing ones too). Off: every aura keeps its spot."] = "开启：图标会紧凑排列（包括“缺失时显示”的图标）。关闭：每个光环都保留自己的位置。"
L["On: it glows while this look shows. Click to switch it."] = "开启：此样式生效期间会发光。点击可切换。"
L["On: the debuffs start on the line after the buffs. Off: they follow straight on."] = "开启：减益效果从增益效果之后的下一行开始。关闭：紧接着增益效果排列。"
L["On: the rule fires only while the conditions below hold. Off drops them."] = "开启：规则仅在下方的条件成立时触发。关闭则忽略这些条件。"
L["On: the skin sets it for every bar that wears it. Off: each bar keeps its own."] = "开启：皮肤会为每个使用它的状态条设置此项。关闭：每个状态条保留自己的设置。"
L["On: the spell's own requirement decides (a proc, enough mana), even on cooldown. Off: only when it can be cast now."] = "开启：由法术自身的条件（触发、法力足够）决定，即使在冷却中也适用。关闭：仅在当前可施放时适用。"
L["On: the trigger fires for your pet's casts of the spell as well as yours."] = "开启：触发器对你的宠物施放该法术时也会触发，与你自己施放时一样。"
L["On: this opacity while none is left. Off: it keeps its opacity."] = "开启：没有剩余时使用此不透明度。关闭：保持原有不透明度。"
L["On: this opacity while toggled on. Off: it keeps its opacity."] = "开启：切换为开启期间使用此不透明度。关闭：保持它原来的不透明度。"
L["On: this trigger has its own pulse duration and animation tuning. Off drops them, and the reminder's apply."] = "开启：此触发器拥有自己的脉冲持续时间和动画调整。关闭则舍弃它们，改用提醒的设置。"
L["Once an ability is off cooldown."] = "技能冷却结束后。"
L["Once the proc glow goes, the pulse this trigger started leaves the screen, the queue and the hold."] = "触发发光消失后，此触发器启动的脉冲会离开屏幕、队列和保持状态。"
L["Once the spell stops being usable, the pulse this trigger started leaves the screen, the queue and the hold."] = "法术不再可用后，此触发器启动的脉冲会离开屏幕、队列和保持状态。"
L["One card per element with its preview, kind, load conditions, Edit and Delete."] = "每个元素一张卡片，含其预览、类型、载入条件、编辑和删除。"
L["One color"] = "单一颜色"
L["One editor for every selected icon (or bar): the rows they all share, read from the first one; a change lands on all of them."] = "为所有选中的图标（或状态条）提供同一个编辑器：显示它们共有的行，数值取自第一个；一处更改会应用到所有。"
L["One layer for every element of this layout, or each element's own layer moved up or down."] = "此布局的所有元素共用一个层级，或把每个元素自己的层级整体上移或下移。"
L["One look"] = "同一个样式"
L["One motion (seconds)"] = "单次动态效果（秒）"
L["One option of a choice talent"] = "选择型天赋的其中一个选项"
L["One per tick"] = "每跳一个"
L["One pulse (seconds)"] = "单次脉冲（秒）"
L["One run (seconds)"] = "单次运行（秒）"
L["One stance"] = "单个姿态"
L["One totem, by its spell ID"] = "一个图腾，按其法术 ID 指定"
L["One totem: any rank, any slot. A totem slot: whatever is in it. My totem bar's pick: its totem, shown with none down; click drops it."] = "一个图腾：任意等级，任意栏位。一个图腾栏位：其中的任何东西。我的图腾栏所选：图腾栏的图腾，没有图腾放下时也显示；点击可放下它。"
L["One you have not learned yet stays grey until you do."] = "尚未学会的会保持灰色，直到你学会它。"
L["One-time catch-up: moves EVERY action bar spell to the top rank you know, including lower ranks you placed on purpose."] = "一次性补齐：把动作条上的每个法术都换成你已学会的最高等级，包括你特意放置的低等级法术。"
L["Only a spell row has a cost to mark."] = "只有法术行才有可标记的消耗。"
