L["Opens Import / Export with just this reminder ticked and its share string ready to copy."] = "打开“导入 / 导出”，仅勾选此提醒，并准备好可复制的分享字符串。"
L["Opens Import / Export with just this ticked and its share string ready to copy."] = "打开“导入 / 导出”，仅勾选此项，并准备好可复制的分享字符串。"
