L["Textures you use show here."] = "你用过的材质会显示在这里。"
L["That anchor target no longer exists, so it stays free."] = "该锚点目标已不存在，因此保持自由。"
L["That frame can't move this way: an Arc Auras frame, the whole screen, or what this group is anchored to."] = "该框架不能这样移动：Arc Auras 的框架、整个屏幕，或此组所锚定的对象。"
L["That paste came in cut short. Paste it once more."] = "粘贴内容被截断了。请再粘贴一次。"
L["The "] = "该"
L["The Active look, its timer running with its swipe and duration text. Drag any text on the icon to place it."] = "“激活”样式，其计时器运行，带冷却转圈和持续时间文字。拖动图标上的任意文字可调整其位置。"
L["The Algeth'ar Puzzle Box's haste: 20 seconds from its use; dying clears it."] = "艾杰斯亚谜题盒的急速效果：使用后持续 20 秒；死亡会清除它。"
L["The Arc Proc's own"] = "Arc 触发自带"
L["The Cooldown Manager look draws the border and the shadow."] = "冷却管理器样式负责绘制边框和阴影。"
L["The Cooldown Manager look sets the picture's size, crop and shape."] = "冷却管理器样式决定图片的大小、裁剪和形状。"
L["The Cooldown Manager's cooldown IDs for spells, auras and trinkets, one line per category. Runs of IDs show as ranges."] = "冷却管理器中法术、光环和饰品的冷却ID，每个类别一行。连续的ID以范围显示。"
L["The Cooldown Manager's soft shadow frame around the icon art."] = "冷却管理器在图标图像周围的柔和阴影框。"
L["The ID block shows only when Shift is held as the tooltip opens."] = "只有在打开鼠标提示时按住 Shift，才会显示 ID 块。"
L["The ID of what the tooltip shows: a spell, aura, item, toy, mount, currency, achievement or quest."] = "鼠标提示所显示内容的 ID：法术、光环、物品、玩具、坐骑、货币、成就或任务。"
L["The Light's Potential potion: 30 seconds from the drink, each drink restarts it; dying clears it."] = "圣光潜力药水：饮用后持续 30 秒，每次饮用都会重新开始；死亡会清除它。"
L["The Not active look, with no timer running."] = "“未激活”样式，没有计时器在运行。"
L["The On cooldown look: the timer idle and its cooldown spell cooling down."] = "“冷却中”样式：计时器空闲，其冷却法术正在冷却。"
L["The Ready look: the timer idle and its cooldown spell ready."] = "“就绪”样式：计时器空闲，其冷却法术已就绪。"
L["The Timer running look, its timer frozen with its swipe and duration text. Drag any text on the icon to place it."] = "“计时器运行中”样式，其计时器定格，带冷却转圈和持续时间文字。拖动图标上的任意文字可调整其位置。"
L["The Tracked Bars entry this bar copies. Keep the Cooldown Manager's own bar on, and hide it with opacity 0 in Edit Mode."] = "此状态条所复制的“追踪的状态栏”条目。请保持冷却管理器自带的状态条开启，并在编辑模式中将其不透明度设为 0 来隐藏。"
L["The action bar's yellow check on the icon while it waits for your next swing."] = "动作条上图标的黄色选中状态，在等待你下一次挥击期间显示。"
L["The art's spell"] = "图像的法术"
L["The aura at 3 stacks."] = "3 层的光环。"
L["The aura comes up with a fake duration (swipe and duration text), drops to its missing look, and comes back."] = "光环以模拟的持续时间出现（冷却转圈和持续时间文字），然后变为缺失样式，再重新出现。"
L["The aura counts down, drops off, and comes back: threshold colours and the duration text."] = "光环倒数、消失，再重新出现：阈值颜色和持续时间文字。"
L["The aura icons in this group are kept for when you switch back."] = "本组中的光环图标会保留，以便你切换回来时使用。"
L["The aura lasts"] = "光环持续"
L["The aura lasts (seconds)"] = "光环持续（秒）"
L["The aura with 60% of its duration left."] = "剩余 60% 持续时间的光环。"
L["The aura's full length, which the game keeps from addons: seconds need it, percent does not. 0 = not set: always shown."] = "光环的总时长，游戏不会告知插件：秒数需要它，百分比不需要。0 = 未设置：始终显示。"
L["The aura's full length. The game hides it from addons, so seconds thresholds need it. 0 = not set: the glow shows the whole time."] = "光环的总时长。游戏会对插件隐藏该值，因此以秒为单位的阈值需要它。0 = 未设置：发光全程显示。"
L["The aura's icon"] = "光环的图标"
L["The aura's spell ID, or the spell whose cooldown it follows: an ID, a link or the name of a spell you know. Enter applies it."] = "光环的法术 ID，或它所跟随冷却的法术：ID、链接或你已学会的法术名称。按 Enter 应用。"
L["The aura's spell IDs, comma separated."] = "光环的法术 ID，以逗号分隔。"
L["The aura's spell IDs, comma separated. Any caster's copy counts."] = "光环的法术 ID，以逗号分隔。任何施放者的那份都算。"
L["The aura's spell IDs, separated by commas or spaces. Add every rank's ID if they differ. The game shows whichever is up."] = "光环的法术ID，以逗号或空格分隔。若各等级ID不同，请添加每个等级的ID。游戏会显示当前存在的那个。"
L["The aura's spell IDs, separated by commas or spaces. Tracking sets its unit."] = "光环的法术 ID，以逗号或空格分隔。“追踪”决定它的单位。"
L["The aura's spell IDs, separated by commas or spaces; any of them counts."] = "光环的法术 ID，以逗号或空格分隔；其中任何一个都算。"
L["The aura's spell IDs, separated by commas or spaces; any of them shows the picture."] = "光环的法术 ID，以逗号或空格分隔；其中任何一个都会显示图片。"
L["The aura's spell IDs, separated by commas. A debuff usually has the ID of the spell that puts it up."] = "光环的法术 ID，以逗号分隔。减益通常与施加它的法术有相同的 ID。"
L["The band your target is in; blank with no target or a friendly one."] = "你的目标所在的区间；没有目标或目标为友方时留空。"
L["The bar"] = "该状态条"
L["The bar at 3 stacks, or at its Max stacks when that is lower."] = "3 层时的状态条，或在“最大层数”较低时取最大层数。"
L["The bar at 60%, standing still."] = "60% 时的状态条，保持静止。"
L["The bar between swings."] = "两次挥击之间的状态条。"
L["The bar in the middle of a cast, standing still."] = "施法进行到一半时的状态条，保持静止。"
L["The bar is full at this many stacks. Empty: the maximum the game reports, shown in the field. Type a number only if it is wrong."] = "状态条在达到此层数时充满。留空：使用游戏报告的最大值（显示在输入框中）。仅当该值有误时才输入数字。"
L["The bar part way through its timer."] = "计时器进行到一半时的状态条。"
L["The bar shows half the power; past the middle it fills again in the second half color."] = "条只显示一半的资源；过了中点后以“后半段颜色”再次填充。"
L["The bar when the reload is done but you are moving: the shot waits for you to stop."] = "装填已完成但你在移动时的状态条：射击会等你停下。"
L["The bar with no timer running."] = "没有计时器运行时的状态条。"
L["The bar's look."] = "状态条的样式。"
L["The bar's own look"] = "状态条自己的样式"
L["The bars that wear it keep its look as their own."] = "使用它的状态条会把它的样式保留为自己的。"
L["The buff this totem gives you, as its tooltip names it. The Out of range look shows while the totem is out and you lack it."] = "此图腾给予你的增益效果，名称以其鼠标提示为准。图腾已放置而你没有该效果时，会显示“超出距离”样式。"
L["The chance climbs 1% per Riptide since the last proc."] = "自上次触发以来，每使用一次激流，几率上升 1%。"
L["The chance climbs per qualifying harvest; needs the 2-piece set."] = "每次符合条件的收获都会提升几率；需要 2 件套装效果。"
L["The chance of a proc"] = "触发几率"
L["The class this skin switches on for."] = "此皮肤为哪个职业启用。"
L["The color %s."] = "颜色 %s。"
L["The cooldown lasts (seconds)"] = "冷却持续时间（秒）"
L["The cooldown swipe keeps its own opacity while the icon dims, so only the art fades."] = "图标变暗时，冷却转圈保持自身的不透明度，只有图像淡出。"
L["The count"] = "计数"
L["The count of your equipped ammo; blank with the slot empty."] = "你已装备弹药的数量；栏位为空时留空。"
L["The count the \"Ammo is low\" load and visibility condition uses. An icon's warning glow and ammo count colors have their own thresholds."] = "“弹药不足”载入和可见性条件所使用的数量。图标的警告发光和弹药数量颜色有各自的阈值。"
L["The countdown stays hidden until this many seconds are left."] = "倒计时在剩余这么多秒之前保持隐藏。"
L["The deck half drawn, with a mark where each proc landed."] = "抽到一半的牌组，每次触发出现的位置都有标记。"
L["The dim copy stays when the picture hides: no aura, no timer, a cooldown not ready."] = "图片隐藏时，变暗的副本会保留：没有光环、没有计时器、冷却未就绪。"
L["The end of your cast that your connection's delay covers: start the next cast once the fill reaches it."] = "你的网络延迟所覆盖的施法末段：填充到达此处后即可开始下一次施法。"
L["The fill behind this group while the options window is open; opacity 0 means none."] = "选项窗口打开时，此组背后的填充；不透明度 0 表示无。"
L["The fill shows how many of this deck's procs are used: none, some or all. Off: the Fill color."] = "填充显示此牌组中已使用的触发数量：无、部分或全部。关闭：使用“填充颜色”。"
L["The first time you log in after Arc Auras updates, a window opens once with what changed in the new version."] = "在 Arc Auras 更新后首次登录时，会打开一次窗口，说明新版本的变化。"
L["The full look starts out of combat, or after a /reload."] = "完整样式在脱离战斗后，或 /reload 后开始生效。"
L["The game does not let addons match this aura type on that unit by spell ID."] = "游戏不允许插件按法术 ID 在该单位上匹配这种光环类型。"
L["The game draws it with the aura, in combat too. Buffs work on you, your pet and friendly units; debuffs on a hostile target or focus."] = "游戏会随光环一起绘制它，战斗中也一样。增益适用于你、你的宠物和友方单位；减益适用于敌对目标或焦点目标。"
L["The game frame's name, as Pick Frame shows it. Enter applies it."] = "游戏框架的名称，如“选取框架”所显示的。按 Enter 应用。"
L["The game holds this frame still in combat. It moves when combat ends."] = "游戏在战斗中会让这个框架保持不动。战斗结束后它才会移动。"
L["The game keeps an aura's length from addons, so seconds need it. A share needs none."] = "游戏不向插件提供光环的时长，所以秒数需要它。分享不需要。"
L["The game keeps the aura's length from addons: 0 shows the words the whole time it is up."] = "游戏不向插件提供光环的时长：0 表示光环存在期间始终显示这些文字。"
L["The game plays aura sounds itself, so they work in combat, for anyone's copy of the aura."] = "光环声音由游戏自己播放，所以战斗中也有效，对任何人的光环都适用。"
L["The game plays it, in combat too; Load When and the gap between cues don't apply."] = "由游戏播放，战斗中也一样；“载入的条件”和提示音之间的间隔不适用。"
L["The game protects %s, so it stays free."] = "游戏保护着 %s，因此它保持自由。"
L["The game sent a spell update"] = "游戏发送了法术更新"
L["The game's clock, as the minimap shows it."] = "游戏时钟，与小地图上显示的一致。"
L["The game's debuff border"] = "游戏的减益效果边框"
L["The game's own cooldown and buff icons and bars, as in its options. Items pinned to its icons stand free until it is back on."] = "游戏自带的冷却和增益图标及状态条，与其选项中一致。固定在其图标上的项目会保持自由，直到它重新开启。"
L["The game's own gold art, untinted, so the color steps aside. Intensity still applies."] = "游戏自带的金色图像，不着色，因此颜色选项不起作用。强度仍然生效。"
L["The global name of a frame, e.g. ElvUF_Player. A frame that does not exist counts as not there."] = "框架的全局名称，例如 ElvUF_Player。不存在的框架视为不在场。"
L["The global name of a game frame, e.g. PlayerFrame or ElvUF_Player."] = "游戏框架的全局名称，例如 PlayerFrame 或 ElvUF_Player。"
L["The glow waits for combat; out of combat the bar shows without it."] = "发光等到战斗中才出现；脱离战斗时，条不带发光显示。"
L["The glow waits for combat; out of combat the icon shows without it."] = "发光等到战斗中才出现；脱离战斗时，图标不带发光显示。"
L["The green outline and dark fill around each group while this window is open. Nothing shows groups as in play. Name tabs still work."] = "此窗口打开期间显示在各组周围的绿色轮廓和深色填充。选择“无”则按游戏时的样子显示各组。名称标签仍可使用。"
L["The group"] = "该组"
L["The group takes its %s with it."] = "该组会带着其 %s 一起移动。"
L["The group's box hugs the icons that are showing; anything anchored to it moves with it."] = "组的框体紧贴正在显示的图标；锚定在其上的任何内容会随之移动。"
L["The group's point"] = "组的点"
L["The group's spot can't be read right now. The frame moves once it can."] = "目前无法读取组的位置。一旦可以读取，框架就会移动。"
L["The groups take their %s with them."] = "各组会带着各自的 %s 一起移动。"
L["The health preview: 65% health with incoming heals and shields, in your colours and texts."] = "生命值预览：65% 生命值，含即将到来的治疗和护盾，使用你的颜色和文字。"
L["The icon"] = "图标"
L["The icon and bar previews sit on this color."] = "图标和状态条预览以这个颜色为底。"
L["The icon as the game's Cooldown Manager draws it: its rounded corners, its border and shadow, and its swipe."] = "图标样式与游戏的冷却管理器一致：圆角、边框、阴影和冷却转圈。"
L["The icon's art and border at this opacity while the rule holds. 0% hides the whole icon, texts and glows too."] = "规则成立期间，图标的图案和边框使用此不透明度。0% 会连同文字和发光一起隐藏整个图标。"
L["The icon's cooldown ID, its exact entry in the Cooldown Manager: Pick Frame on an icon fills it. Empty uses the spell above."] = "该图标的冷却ID，即它在冷却管理器中的确切条目：在图标上使用“选取框架”会填入。留空则使用上方的法术。"
L["The icon's exact entry in the Cooldown Manager; Pick Frame on an icon fills it. Empty uses the spell above."] = "图标在冷却管理器中的确切条目；对图标使用“选取框架”即可填入。留空则使用上方的法术。"
L["The icon's file ID, the base icon when an override swapped the art, and the icon the button shows when that differs."] = "图标的文件 ID、被覆盖替换图像时的基础图标，以及与之不同时按钮所显示的图标。"
L["The import did not run."] = "导入未执行。"
L["The internal cooldown as a timer: 45 s, less with Natural Harmony."] = "以计时器显示内置冷却：45 秒，拥有自然和谐时更短。"
L["The item"] = "该物品"
L["The item's own stacks, before this rule acts. Empty = no such condition."] = "该物品自身的数量，在此规则生效之前。留空 = 无此条件。"
L["The item, or several: the icon shows the first one you carry and can use."] = "该物品，或多个物品：图标显示你携带且可使用的第一个。"
L["The items that used the old values take the new ones."] = "使用旧值的项目会采用新值。"
L["The items you have keep their look; only new ones start with these. Leaving the page does the same."] = "你已有的项目保留它们的样式；只有新的项目才从这些值开始。离开页面也有同样效果。"
L["The kinds that take this page's rows, each where it has the row. Nothing happens until you press Copy."] = "采用此页各行的类型，各自在拥有该行的地方生效。在你点击复制之前不会有任何变化。"
L["The label's own color"] = "标签自身的颜色"
L["The last 0.5 s of the bar is Auto Shot's windup: it fills only while you stand still. Colors on the Appearance tab."] = "状态条的最后0.5秒是自动射击的瞄准阶段：只有站着不动时才会填充。颜色在“外观”标签页中设置。"
L["The layout's center point"] = "布局的中心点"
L["The layout's distance from the spot it's pinned to, in whole units."] = "布局与其固定点之间的距离，单位为整数。"
L["The line to speak."] = "要朗读的话。"
L["The look the rows below change. The bar shows it while you edit; anything a look leaves alone follows the bar's own."] = "下方各行所修改的样式。编辑时状态条会显示它；样式未涉及的内容跟随状态条自己的设置。"
L["The look the rows below edit. Bar's own applies when no skin does. A skin applies when its conditions hold, first from the top."] = "下方各行所编辑的样式。没有任何皮肤生效时，使用“状态条自身”。皮肤在其条件满足时生效，从上往下第一个优先。"
L["The look while the aura is missing: the ghost with its Missing icon, alpha and desaturation."] = "光环缺失时的样式：带“缺失”图标、不透明度和去色的幽灵图像。"
L["The look while the aura is up: Aura Active art, alpha, tint, border and glow. Drag any text to place it."] = "光环存在期间的样式：光环激活的图案、不透明度、着色、边框和发光。拖动任意文字可调整其位置。"
L["The look while the aura is up: its button over the cooldown, in the Aura Active look, with stacks. Drag texts to place them."] = "光环存在期间的样式：其按钮以光环激活的样式显示在冷却之上，并带有层数。拖动文字可调整其位置。"
L["The look while you are in the stance (any stance, for your current one). Drag any text on the icon to place it."] = "你处于该姿态时的样式（选“任意姿态”时，针对你当前所处的姿态）。拖动图标上的任意文字可调整其位置。"
L["The look while you are not in it (no stance, for your current one)."] = "你不处于该姿态时的样式（选“无姿态”时，针对你当前的状态）。"
L["The mana the next tick adds glows past the fill, brightens as the tick nears, then lands. Empty while the five-second rule runs."] = "下一跳将恢复的法力会在填充之外发光，随着这一跳临近而变亮，然后落下。五秒规则期间为空。"
L["The middle of your screen"] = "屏幕中央"
L["The mirror is not loaded."] = "镜像未载入。"
L["The move did not run."] = "移动未执行。"
L["The nearest band that shows, standing still."] = "显示的最近区间，保持静止。"
L["The new look shows after a reload"] = "新样式将在重载界面后显示"
L["The next tick"] = "下一跳"
L["The number beside a marker that comes back in a later swing."] = "标记旁边的数字，该标记会在之后的某次挥击中再次出现。"
L["The numeric item ID."] = "数字形式的物品 ID。"
L["The opacity starts with this many seconds left."] = "剩余这么多秒时，该不透明度开始生效。"
L["The original bright cyan."] = "原本的亮青色。"
L["The pack items you deleted come back with this update. Unticked, they stay deleted."] = "你删除的包内项目会随此更新恢复。取消勾选则保持删除状态。"
L["The pack's name. Whoever imports the string sees it first."] = "包的名称。导入字符串的人会先看到它。"
L["The part of a shield that doesn't fit past full health draws over the end of the health, so a shield on a full-health unit still shows."] = "超出满生命值而放不下的那部分护盾会绘制在生命值条的末端上方，因此满血单位身上的护盾也能显示。"
L["The picture again, dimmed, behind it: the empty part of a fill. It hides with the picture."] = "图片再次以变暗的样子绘制在其后方：即填充的空白部分。它随图片一同隐藏。"
L["The picture as it looks while active; a fill or a ring stands at 60%."] = "图片处于激活状态时的样子；填充或圆环停在 60%。"
L["The picture grows and shrinks gently, in combat too."] = "图片会轻轻放大缩小，战斗中也一样。"
L["The picture is a sheet of frames, played in order over and over."] = "图片是一张帧序列图，按顺序循环播放。"
L["The picture keeps its shape at any width and height: its edges are cropped, never stretched."] = "无论宽高如何，图片都保持原有形状：边缘会被裁剪，绝不拉伸。"
L["The picture, border, swipe, shadow and glows follow the shape."] = "图片、边框、冷却转圈、阴影和发光都会跟随该形状。"
L["The point of the frame that goes on the group."] = "框架上放到组上的那个点。"
L["The power this row holds on. All powers: whatever power the bar shows."] = "此行对哪种资源生效。所有资源：状态条显示的任何资源。"
L["The pulse stays at full, with no fade, until you cast the spell or use the item, or its trigger's Clear when ends it."] = "脉冲会保持最强且不淡出，直到你施放该法术或使用该物品，或触发器的“清除条件”将其结束。"
L["The ready look with no animation. Drag any text on the icon to place it."] = "没有动画的就绪样式。拖动图标上的任意文字可调整其位置。"
L["The ready look, with the Ready text when it is on."] = "就绪样式，若开启了“就绪”文字则一并显示。"
L["The reload is done but you are moving: the shot waits for you to stop."] = "装填已完成但你在移动：射击会等你停下。"
L["The resize lands when you let go of the slider."] = "缩放在你松开滑块时生效。"
L["The resource texts change color at their own power values, apart from the bar's colors."] = "资源文字按各自的资源值变色，与条的颜色无关。"
L["The resource texts wear the fill's color, the bar's own or a row's. A row's own text color wins."] = "资源文字使用填充的颜色，即条自身的颜色或某一行的颜色。某一行自己的文字颜色优先。"
L["The row holds for any spell left in it."] = "只要其中还剩任何法术，该行就生效。"
L["The rule fires only while this spell is off its cooldown (the GCD never counts). Empty = no such condition."] = "仅当此法术不在冷却中时规则才触发（GCD 不计入）。留空 = 无此条件。"
L["The same enchant counting down, as it looks in play."] = "同一个附魔在倒数，与实际游戏中的样子一致。"
L["The same totem counting down, as it looks in play."] = "同一个图腾在倒数，与实际游戏中的样子一致。"
L["The set gate is the Set Pieces Rule on Load Conditions."] = "套装门槛由“载入条件”里的“套装部件规则”设置。"
L["The sets on the gear you wear now are listed; with fewer pieces on, the item goes inert."] = "列出你当前所穿装备上的套装；穿戴的部件数不足时，该物品会失效。"
L["The shield is in Appearance > Icon, the color in Appearance > Fill & Colors."] = "护盾在“外观”>“图标”中，颜色在“外观”>“填充和颜色”中。"
L["The specs this skin switches on in. Pick several or Any spec."] = "此皮肤启用的专精。可选多个或“任意专精”。"
L["The spell that puts it down. The bar follows that totem or guardian, any rank, in any slot. Empty: whatever is in the slot."] = "放置它的法术。状态条会跟随该图腾或守护者，不论等级，不论在哪个栏位。留空：栏位中是什么就跟随什么。"
L["The spell that puts it down. The icon follows that totem or guardian, any rank, in any slot. Empty: whatever is in the slot."] = "放置它的法术。图标会跟随该图腾或守护者，不论等级，不论在哪个栏位。留空：栏位中是什么就跟随什么。"
L["The spell that puts it down: the icon follows that totem or guardian, any rank, into whatever slot it lands."] = "放下它的法术：图标会跟随该图腾或守护者，任意等级，无论落在哪个栏位。"
L["The spell that puts the totem down, any rank. Empty: this icon's spell."] = "放下图腾的法术，任意等级。留空：使用此图标的法术。"
L["The spell whose button or icon it rides: a spell ID, a link or the name of a spell you know. Enter applies it."] = "它所依附的按钮或图标对应的法术：法术 ID、链接或你已学会的法术名称。按 Enter 应用。"
L["The spell whose button or icon it rides: an ID, a link or a known spell's name. Several ranks may be listed. Enter applies."] = "它所跟随的按钮或图标对应的法术：可输入ID、链接或已知法术的名称。可列出多个等级。按 Enter 应用。"
L["The spell whose cooldown it shows. Empty: the art's spell."] = "它所显示冷却的法术。留空：使用图案所属的法术。"
L["The spell whose icon it wears. A spell ID, a link, or the name of a spell you know."] = "它所采用图标的法术。法术 ID、链接，或你已学会的法术名称。"
L["The spell whose icon it wears; Appearance > Icon > Art > Custom icon wins over it. A spell ID, a link, or the name of a spell you know."] = "其图标所取自的法术；“外观”>“图标”>“图像”>“自定义图标”优先于它。可填法术 ID、链接，或你已学会的法术名称。"
L["The spell whose range picks the band: a melee ability for Melee, a ranged spell for Caster. Empty: your class's usual one."] = "其距离决定区间的法术：“近战”用近战技能，“施法者”用远程法术。留空：使用你职业的常用法术。"
L["The spell whose range to your target decides the dim: an ID or a known spell's name. Empty: your class's usual one."] = "其到目标的距离决定变暗的法术：可输入法术ID或已知法术的名称。留空：使用你职业的常用法术。"
L["The spell whose range to your target decides the rule: an ID or a known spell's name. Any rank works."] = "其到目标的距离决定规则的法术：可输入法术ID或已知法术的名称。任何等级都可以。"
L["The spell's icon"] = "法术的图标"
L["The spell's name or ID."] = "法术的名称或 ID。"
L["The spells it watches (any spell but these: the ones it skips), comma separated: IDs, links or names. Any rank."] = "它监视的法术（除这些以外的任何法术：即它会跳过的法术），以逗号分隔：ID、链接或名称。任意等级。"
L["The spot on your screen the layout keeps its distance from when the resolution or UI scale changes."] = "当分辨率或界面缩放改变时，布局与之保持距离的屏幕位置。"
L["The stack count"] = "层数"
L["The stack count that fills it. 0 = the aura's most, or the custom item's Max stacks."] = "使其填满的层数。0 = 光环的最大层数，或自定义物品的“最大层数”。"
L["The stacks"] = "层数"
L["The stacks climb to Max stacks, then clear: the fill and the count."] = "层数上升到“最大层数”后清零：填充和计数。"
L["The stacks climb to the maximum and drop: stack colours, the max colour and the count."] = "层数上升到最大值后回落：层数颜色、最大值颜色和计数。"
L["The stacks, then the timer in brackets: 3 (7.2)."] = "先是层数，然后是括号中的计时器：3 (7.2)。"
L["The stance or form you are in, or one lit while you are in it."] = "你所处的姿态或形态，或在你处于其中时亮起的那一个。"
L["The stance's spell ID: one this character does not have, such as another class's."] = "姿态的法术 ID：可以是此角色没有的，例如其他职业的。"
L["The state that lights it: an aura up or missing, or a spell Ready, Recharging (a charge used) or On cooldown (none left)."] = "使其亮起的状态：光环存在或缺失，或法术就绪、充能中（已用掉一个充能）、冷却中（没有剩余）。"
L["The swipe keeps its own opacity while Active opacity dims the icon, so only the art fades."] = "激活不透明度使图标变暗时，冷却转圈保持自身的不透明度，只有图像淡出。"
L["The text"] = "该文字"
L["The text to speak is set on each trigger."] = "要朗读的文字在每个触发器上设置。"
L["The text with a sample value, in its font, colour and box."] = "带示例数值的文字，使用它的字体、颜色和文本框。"
L["The texture"] = "该材质"
L["The time left"] = "剩余时间"
L["The time left on a weapon's enchant, with its charges."] = "武器附魔的剩余时间及其充能次数。"
L["The time left on one of your totems or guardians, by the spell that puts it down or by its slot."] = "你的某个图腾或守护者的剩余时间，按放下它的法术或按其栏位指定。"
L["The timer"] = "计时器"
L["The timer is not running"] = "计时器未运行"
L["The timer is running"] = "计时器运行中"
L["The timer runs"] = "计时器运行"
L["The timer runs or stacks are above 0"] = "计时器运行或层数大于 0"
L["The timer runs out, rests, and starts again."] = "计时器结束，休息一会儿，然后重新开始。"
L["The top look wins when several hold."] = "多个样式同时成立时，最上面的生效。"
L["The totem bar button this icon follows."] = "此图标跟随的图腾栏按钮。"
L["The totem or guardian slot to watch. The icon lights while anything is in it."] = "要监视的图腾或守护者栏位。栏位中有任何东西时图标就会亮起。"
L["The totem or guardian slot to watch. The icon lights while anything is in it. A shaman's slots hold: %s."] = "要监视的图腾或守护者栏位。栏位中有任何内容时图标亮起。萨满祭司的栏位包含：%s。"
L["The tracked cooldown spell."] = "被追踪的冷却法术。"
L["The tracked item, or several: the icon shows the first one you carry and can use. Retargeting keeps every setting and position."] = "被追踪的物品，可填多个：图标显示你携带且能使用的第一个。更换目标会保留所有设置和位置。"
L["The tracked spell. Retargeting re-keys the driver and keeps every setting and position."] = "被追踪的法术。更换目标会重新绑定驱动，并保留所有设置和位置。"
L["The tracker's readout when you point at the icon. On also turns the icon's click-through off."] = "鼠标指向图标时显示追踪器的读数。开启时也会关闭图标的点击穿透。"
L["The unit's name"] = "单位的名称"
L["The value counts power (45 energy, 2000 mana) instead of a percent of the bar."] = "该数值按资源值计（45 点能量、2000 点法力），而不是状态条的百分比。"
L["The value runs from empty to full and back: threshold colours, pips and every text follow it."] = "数值从空到满再回落：阈值颜色、分段点和所有文字都随之变化。"
L["The wheel"] = "该轮盘"
L["The wheel is full: empty a spot first."] = "轮盘已满：请先清空一个位置。"
L["The whole cooldown"] = "整个冷却"
L["The whole picture"] = "整张图片"
L["The windup as it fills, and a faint outline of its spot while you reload."] = "瞄准阶段填充时的颜色，以及装填期间标出其位置的淡色轮廓。"
L["Their own class and spec checks"] = "它们自己的职业和专精检查"
L["Their own class checks"] = "各自的职业检查"
L["Then"] = "然后"
L["Thick line"] = "粗线"
L["Thick outline"] = "粗描边"
L["Thickness"] = "粗细"
L["Thin line"] = "细线"
L["Third"] = "第三个"
L["Third ammo threshold (at or below)"] = "第三弹药阈值（小于等于）"
L["Third ammo threshold color"] = "第三弹药阈值颜色"
L["Third threshold (%)"] = "第三阈值（%）"
L["Third threshold color"] = "第三阈值颜色"
L["This %s fails its load conditions on this character (%s). You can still edit it. Click its eye to show it on screen."] = "此%s在这个角色上不满足载入条件（%s）。你仍可编辑它。点击其眼睛图标可将其显示在屏幕上。"
L["This bar doesn't load on this character (%s). Click its eye to show it while you edit."] = "此状态条未在这个角色上载入（%s）。点击其眼睛图标可在编辑时显示它。"
L["This bar wears as many skins as it can."] = "此状态条会尽可能多地采用皮肤。"
L["This bar's aura"] = "此状态条的光环"
L["This bar's name"] = "此条的名称"
L["This bar's spell"] = "此状态条的法术"
L["This character"] = "此角色"
L["This frame stops moving with the group and goes back to where it was."] = "这个框架不再随组移动，并回到原来的位置。"
L["This group doesn't load on this character (%s). Click its eye to show it while you edit."] = "此组未在这个角色上载入（%s）。点击其眼睛图标可在编辑时显示它。"
L["This group follows the cursor or a nameplate. A frame can't keep up with it."] = "此组跟随光标或姓名板。框架无法跟上它。"
L["This group holds %d icons, and they would not fit. Move one out first."] = "此组包含%d个图标，放不下。请先移出一个。"
L["This group is not on screen, so the frame stays where it was."] = "此组不在屏幕上，所以框架保持在原来的位置。"
L["This group reminds you of it already."] = "这个组已经在提醒你了。"
L["This group shows up to %d auras already."] = "此组已经最多显示%d个光环。"
L["This hero tree is not the one chosen."] = "这不是所选的英雄天赋树。"
L["This icon doesn't load on this character (%s). Click its eye to show it while you edit."] = "此图标未在这个角色上载入（%s）。点击其眼睛图标可在编辑时显示它。"
L["This icon's own rules wait until Close gaps is off: set these on the Aura Group."] = "此图标自己的规则要等“填补空隙”关闭后才生效：请在光环组上设置。"
L["This is how Arc Auras speaks."] = "这就是 Arc Auras 说话的方式。"
L["This item itself: not offered"] = "此项目本身：不提供"
L["This layout doesn't load on this character (%s). Click its eye to show it while you edit."] = "此布局未在这个角色上载入（%s）。点击其眼睛图标可在编辑时显示它。"
L["This layout stops setting these. Everything that followed it goes back to its own defaults."] = "此布局将不再设置这些。所有跟随它的内容都会恢复为各自的默认值。"
L["This option is active"] = "此选项已激活"
L["This option is not active"] = "此选项未激活"
L["This spell has no charges: Recharging never lights."] = "此法术没有充能：“充能中”永远不会亮起。"
