L["What drives it"] = "由什么驱动"
L["What else can change this icon's look, glow or sound."] = "还有什么可以改变此图标的样式、发光或声音。"
L["What every type shares: wash strength, label size and spot, glow size, and the order of a full look."] = "所有类型共有的内容：着色强度、标签大小和位置、发光大小，以及完整样式的顺序。"
L["What it anchors to. Anchors added after it are tried in order while it is not on screen."] = "它所锚定的对象。当它不在屏幕上时，会按顺序尝试其后添加的锚点。"
L["What it does, and when"] = "作用与时机"
L["What it says. Enter applies it."] = "它显示的内容。按 Enter 应用。"
L["What it says. Tracking can change it later."] = "它显示的内容。之后“追踪”可能会更改它。"
L["What lights this glow: an aura (a buff or debuff, on any unit) or a spell's cooldown."] = "什么会点亮此发光：光环（任意单位上的增益或减益）或法术的冷却。"
L["What the bar says while the target is in this band."] = "目标在此区间内时条上显示的文字。"
L["What the pack is for, or what changed in this version."] = "这个包的用途，或此版本的更改内容。"
L["What the sidebar calls it."] = "侧边栏中显示的名称。"
L["What the stack text shows. Tokens: {left} {drawn} {size} {procs} {procsLeft} {max} {chance} {viol} {count}. Empty: the Arc Proc's own."] = "层数文字所显示的内容。占位符：{left} {drawn} {size} {procs} {procsLeft} {max} {chance} {viol} {count}。留空：使用 Arc 触发自带。"
L["What this page sets. An item's layout looks and its own values win over it; Arc's default is what it starts from."] = "此页所设置的内容。项目所属布局的样式和它自己的值优先于此处；Arc 的默认值是它的起点。"
