L["When the timer ends"] = "计时器结束时"
L["When the timer runs out, the stacks go back to 0 with it."] = "计时器耗尽时，层数也会回到 0。"
L["When the timer starts"] = "计时器开始时"
L["When two apply at once, the one higher in the list wins."] = "两个同时生效时，列表中靠上的优先。"
L["When usable"] = "可用时"
