L["When you learn a new rank, action bar buttons with the old top rank move up to it. Lower ranks and macros stay."] = "学会新等级后，动作条上放着旧的最高等级的按钮会升级为新等级。较低等级和宏保持不变。"
L["When you learn a new rank, your action bar buttons move up to it, out of combat."] = "学会新等级时，你的动作条按钮会在脱离战斗后升级为该等级。"
L["Where Position X and Y count from. Either way it moves and scales with its layout."] = "位置 X 和 Y 的计算起点。无论哪种方式，它都会随其布局移动和缩放。"
L["Where a group, icon or bar shared without its layout lands. It starts on a layout that loads on this character."] = "不带布局分享的组、图标或状态条放到哪里。默认选中一个会在此角色上载入的布局。"
L["Where an ability comes off cooldown: this swing, or a later one marked +1, +2."] = "技能结束冷却的位置：本次挥击，或标记为 +1、+2 的后续挥击。"
L["Where an icon goes when it shows again. Only for a single row or column."] = "图标再次显示时所在的位置。仅适用于单行或单列。"
L["Where each item sits (its group, or free and where), its anchor, sizes, strata and mouse. Off keeps your own placement."] = "每个项目的位置（所在的组，或自由放置及其位置）、锚点、大小、框架层级和鼠标交互。关闭则保留你自己的摆放。"
L["Where it sits: its edge against the group's."] = "它所处的位置：它的边缘对着组的边缘。"
L["Where on the group that point goes."] = "该点放在组上的哪个位置。"
L["Where the layout's center point (the cross on the map) sits from the spot it's pinned to, in whole pixels."] = "布局的中心点（地图上的十字）与其固定点之间的距离，单位为整数像素。"
L["Where the selection goes: free in a layout, or into a group for icons. A selected group brings its icons. Press Move or Copy to apply."] = "所选内容的去向：布局中的自由位置，或图标所在的组。选中的组会连同其图标一起移动。按“移动”或“复制”才会生效。"
L["Where they load"] = "载入位置"
L["Where this sub-panel's rows go: all of this type, one layout, one group, one item, or all icons of this kind. Press Copy to apply."] = "此子面板各行的复制目标：此类型的全部、某个布局、某个组、某个项目，或此种类的所有图标。按“复制”才会生效。"
L["Where to find the pack or you, a page or a Discord. It shows as text to copy."] = "在哪里能找到这个包或你本人，一个网页或 Discord。它显示为可复制的文字。"
L["Which Casts"] = "哪些施法"
L["Which of the game's volume sliders the sounds follow. Spoken words use WoW's text to speech volume."] = "声音跟随游戏的哪个音量滑块。朗读的文字使用 WoW 的文本转语音音量。"
L["Which one"] = "哪一个"
L["Which part of each picture stays when its edges are cropped."] = "裁剪边缘时，每张图片保留哪一部分。"
L["Which part of the picture stays when its edges are cropped."] = "裁剪边缘时，图片保留哪一部分。"
L["Whichever lands first"] = "先到者为准"
