L["While %s"] = "%s 期间"
L["While a charge comes back it keeps Recharging's look: can't use, not enough resource and out of range wait until it is ready."] = "充能恢复期间保持“充能中”的样式：无法使用、资源不足和超出距离的状态要等它就绪后才显示。"
L["While a totem or guardian from the first spell is out, the icon shows its time instead of the aura."] = "第一个法术的图腾或守护者存在期间，图标显示其时间，而不是光环。"
L["While active"] = "激活期间"
L["While all procs are used"] = "所有触发都已使用时"
L["While all procs used"] = "所有触发都已使用时"
L["While an ability waits to go off with your next swing."] = "当某个技能等待随你下一次挥击生效时。"
L["While casting"] = "施法期间"
