L["While it is on cooldown"] = "冷却期间"
L["While it is queued without the rage or mana to pay for it, the icon takes this color: that swing lands as a plain hit."] = "已排队但没有足够的怒气或法力支付时，图标采用此颜色：那次挥击只是普通攻击。"
L["While it is ready"] = "就绪期间"
