L["While its timer is idle it shows this spell's cooldown, then its Ready look."] = "计时器空闲时，它显示此法术的冷却，然后显示其“就绪”样式。"
L["While missing"] = "缺失期间"
L["While not active"] = "未激活期间"
L["While on cooldown"] = "冷却期间"
