L["While suggested"] = "被推荐期间"
L["While the aura is missing"] = "光环缺失期间"
L["While the aura is up"] = "光环存在期间"
L["While the aura is up the game shows it over the icon: its time, and gone the moment it drops. Works in combat."] = "光环存在期间，游戏会把它显示在图标上方：显示其剩余时间，光环一消失就消失。战斗中有效。"
L["While the aura is up, its border takes the game's color for its type: Magic, Curse, Disease or Poison. Others keep the border color."] = "光环存在期间，其边框使用游戏中对应类型的颜色：魔法、诅咒、疾病或中毒。其他类型保持边框颜色。"
L["While the aura is up, only once little time is left, only while the aura is missing, or always. Works in combat."] = "光环存在期间、仅在剩余时间不多时、仅在光环缺失期间，或始终。战斗中有效。"
L["While the button is held"] = "按住按钮期间"
L["While the timer is idle at 0 stacks, the count shows this many: a pool reads full before its first use. Empty = off."] = "计时器在 0 层空闲时，计数显示这个数量：资源池在首次使用前读数为满。留空 = 关闭。"
L["While the timer runs"] = "计时器运行期间"
L["While this bar is not loaded, its count stops until the next reset."] = "此条未载入期间，其计数会停止，直到下次重置。"
L["While this icon is not loaded, its count stops until the next reset."] = "此图标未载入期间，其计数会停止，直到下次重置。"
L["While this window is open a dim icon marks the spot; drag its name tab to move it."] = "此窗口打开时，一个变暗的图标标出位置；拖动其名称标签可移动它。"
L["While this window is open the outline marks the spot; drag its name tab to move it."] = "此窗口打开时，描边标出位置；拖动其名称标签可移动它。"
L["While this window is open, a dim copy of the first reminder's icon marks where pulses land. On shows only the outline and name tab."] = "此窗口打开时，第一个提醒图标的变暗副本会标出脉冲出现的位置。开启时只显示描边和名称标签。"
L["While this window is open, drag this item's texts where they sit on screen. X and Y follow."] = "此窗口打开时，可在屏幕上拖动此项目的文字到所需位置。X 和 Y 随之更新。"
L["While this window is open, each group shows its name on its top edge, which you drag it by. Off: a small green handle, name on hover."] = "此窗口打开期间，每个组的上边缘会显示其名称，拖动它即可移动该组。关闭：显示一个绿色小把手，鼠标悬停时显示名称。"
L["While this window is open, icons and bars carry a small Edit button that opens them here. Pick which kind shows it, or none."] = "此窗口打开期间，图标和状态条上带有一个小的编辑按钮，可在此处打开它们。选择哪种类型显示该按钮，或选择无。"
L["While this window is open, items that fail their load conditions are drawn anyway, so you can place and style them."] = "此窗口打开期间，不满足载入条件的项目也会照常显示，方便你摆放并调整其样式。"
L["While this window is open, the group you edit shows edge arrows: green adds a row or column on that side, red removes one."] = "此窗口打开期间，正在编辑的组边缘会显示箭头：绿色在该侧添加一行或一列，红色则移除一行或一列。"
L["While toggled on"] = "切换为开启期间"
L["Who carries the aura. Buffs match on friends and you, debuffs on enemies."] = "谁携带该光环。增益匹配友方和你自己，减益匹配敌人。"
L["Who carries the aura: a buff on you, a debuff on your target, or another unit."] = "谁携带该光环：你身上的增益、你目标身上的减益，或其他单位。"
L["Who carries the aura: buffs on you, your pet, party and friends, debuffs on enemies. The game hides the opposite from addons."] = "光环的携带者：增益效果在你、你的宠物、队友和友方身上，减益效果在敌人身上。相反的情况游戏会对插件隐藏。"
L["Who carries the aura: you for a buff, your target for a debuff. You, then your target: you first. Other combinations stay dark."] = "光环的携带者：增益效果看你，减益效果看你的目标。“你，然后目标”：先检查你。其他组合不会显示。"
L["Whole shards only"] = "仅整枚碎片"
L["Whose aura"] = "谁的光环"
L["Whose casts"] = "谁的施法"
L["Wide (3:2)"] = "宽（3:2）"
L["Width"] = "宽度"
L["Width (0 = auto)"] = "宽度（0 = 自动）"
L["Windfury Totem"] = "风怒图腾"
L["Windfury Weapon"] = "风怒武器"
L["Windup"] = "瞄准阶段"
L["Windup color"] = "瞄准阶段颜色"
L["Wing Clip for melee, then Auto Shot with the 10 and 20 yard checks."] = "近战用摔绊，然后是自动射击，带 10 码和 20 码检查。"
L["Wing Clip for melee, then Auto Shot with the 20 yard check."] = "近战用摔绊，然后是自动射击，带 20 码检查。"
L["Wins over the rows below it."] = "优先于其下方的行。"
L["With"] = "剩余"
L["With "] = "拥有 "
L["With %s"] = "拥有 %s"
L["With %s left. Click to change it."] = "剩余 %s。点击可更改。"
L["With Close gaps on, set these on the Aura Group."] = "开启“填补空隙”后，请在光环组上设置这些。"
L["With Close gaps on, the game places the row: these apply only while this window is open."] = "开启“填补空隙”后，由游戏安排该行：这些设置仅在此窗口打开时生效。"
L["With a two-hander, a shield or nothing in this hand, the icon doesn't load. It comes back when you equip a weapon there."] = "此手持有双手武器、盾牌或什么都没有时，图标不会载入。在那里装备武器后会恢复。"
L["With both aura types, or on nameplates, it shows as Colors and badges."] = "同时选择两种光环类型，或在姓名板上时，显示为“颜色和徽章”。"
L["With both, the hide list applies to the buffs only."] = "同时选择两者时，隐藏列表只作用于增益效果。"
L["With both, the hide list applies to the debuffs only."] = "同时选择两者时，隐藏列表只作用于减益效果。"
L["With more than one row and column, a returning icon always takes its spot back."] = "行和列都多于一个时，返回的图标总会夺回原位。"
L["With no charges"] = "没有充能时"
L["With or without a talent"] = "有或没有某个天赋"
L["With several out at once: the First, the Second... Counted by picks how they are counted."] = "同时存在多个时：第一个、第二个……“计数方式”决定如何计数。"
L["With the bar"] = "随条一起"
L["With the look set here"] = "使用此处设置的样式"
L["With this window open, every icon keeps its spot."] = "此窗口打开时，每个图标都保持在原位。"
L["With your weapon (%.2f speed)"] = "使用你的武器（速度 %.2f）"
L["Within"] = "范围内"
L["Within seconds"] = "在多少秒内"
L["Within seconds after rule"] = "规则之后多少秒内"
L["Without "] = "没有 "
L["Without %s"] = "没有 %s"
L["WoW Forever"] = "WoW Forever"
L["WoW Forever: follows the rank you currently know, by name, so a new rank needs no new ID. Off: tracks the exact ID above."] = "WoW Forever：按名称跟随你当前已学的等级，因此新等级无需新ID。关闭：追踪上方的确切ID。"
L["WoW's own option: a short tick when a spoken line ends."] = "WoW 自带选项：语音结束时发出一声短促的提示音。"
L["WoW's own text to speech volume, so it also sets chat narration."] = "WoW 自己的文本转语音音量，因此也会设置聊天朗读的音量。"
L["WoW's voice"] = "WoW 语音"
L["WoW's voice is the one picked in WoW's own options. Male or female picks a matching voice from your system's list."] = "“WoW 语音”是在 WoW 自己的选项中选定的那个。男声或女声会从你系统的列表中选取匹配的语音。"
L["Wobble"] = "摇摆"
